
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_lc_wpbe08_whs_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_lc_wpbe08_whs", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.115638588840481e+00, -4.032892803651905e+00, -3.917022364207855e+00, -3.756674701728618e+00, -3.538525042019201e+00, -3.248921353997222e+00, -2.877742740267123e+00, -2.425284356177194e+00, -1.911051059785545e+00, -1.374541609071362e+00, -8.504605626118179e-01, -5.174450016764258e-01, -4.295280513784643e-01, -3.162132185789424e-01, -1.779715287035084e-01, -6.439243477015107e-02, -9.666090289798807e-03, -2.431365141293426e-04, -2.131732052963367e-06, -2.943810186254133e-09]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


